const RAM=new Map();
async function remote(url,ttl=900){const old=RAM.get(url);if(old&&Date.now()-old.time<ttl*1000)return old.value;const r=await fetch(url,{headers:{'User-Agent':'Mozilla/5.0'},signal:AbortSignal.timeout(14000),cf:{cacheTtl:ttl,cacheEverything:true}});if(!r.ok)throw Error('Source '+r.status);const value=await r.text();if(RAM.size>150)RAM.delete(RAM.keys().next().value);RAM.set(url,{time:Date.now(),value});return value;}
function parseCards(s,cat){let a=[];for(const m of s.matchAll(/<a[^>]*href="[^"]*aid=(\d+)"[^>]*class="product-card"[^>]*>([\s\S]*?)<\/a>/g)){const b=m[2],im=b.match(/<img[^>]*src="([^"]+)"/),t=b.match(/<h3[^>]*>([\s\S]*?)<\/h3>/),p=b.match(/class="price"[^>]*>\$?([\d.]+)/);if(im&&t&&p)a.push({aid:m[1],title:strip(t[1]),image:abs(im[1]),price:+p[1],cat});}const total=s.match(/共<strong>(\d+)<\/strong>页\s*<strong>(\d+)<\/strong>条/);return{items:a,pages:total?+total[1]:1,total:total?+total[2]:a.length};}
async function category(cat,page=1){const fallback=CATALOG[cat];if(fallback.items.length>=fallback.total)return {...fallback,items:fallback.items.slice((page-1)*48,page*48),pages:Math.ceil(fallback.items.length/48)};if(page===1)return fallback;try{return await remote('https://kakobuymake.com/?m=home&c=Lists&a=index&tid='+cat+'&page='+page).then(s=>parseCards(s,cat));}catch{return{items:[],pages:fallback.pages,total:fallback.total,error:true};}}
function fromWeidian(html){let m=html.match(/id="__rocker-render-inject__" data-obj="([^"]+)"/);if(!m)throw Error('Seller unavailable');const d=JSON.parse(decode(m[1])).result.default_model.item_info;return{gallery:(d.imgs||[]).filter(u=>!BLOCKED_IMAGES.includes(u)),sourceName:d.item_name,cny:parseFloat(d.price||d.origin_price),sourceAvailable:true};}
// Import warehouse references from the matching main-site listing, separately from seller images.
function fromMainListing(html,expectedId){
 const clean=html.replace(/<!--[\s\S]*?-->/g,''),id=clean.match(/itemID(?:%3D|=)(\d+)/)?.[1];
 if(expectedId&&id&&id!==expectedId)throw Error('QC listing identity mismatch');
 const gallery=clean.match(/<div\b[^>]*class=["']product-gallery["'][^>]*>([\s\S]*?)<div\b[^>]*class=["']product-details["'][^>]*>/i)?.[1];
 if(!gallery)throw Error('QC gallery unavailable');
 const images=[];
 for(const match of gallery.matchAll(/<img\b[^>]*\bsrc=["']([^"']+)["'][^>]*>/gi)){
  try{const url=new URL(decode(match[1]),'https://kakobuymake.com');
   if(url.protocol!=='https:'||url.hostname!=='kakobuymake.com'||url.username||url.password||!/^\/uploads\/.+\.(?:jpe?g|png|webp)$/i.test(url.pathname)||BLOCKED_IMAGES.includes(url.href))continue;
   if(!images.includes(url.href))images.push(url.href);
  }catch{}
 }
 if(!images.length)throw Error('QC gallery contains no source images');
 // First image is the catalog cover, also repeated by its active thumbnail.
 return {...(id?{id}:{}),sourceQc:images.slice(1),qcStatus:images.length>1?'available':'missing'};
}
async function product(aid){
 const known=aid==='7896594713'?FEATURES.sample:FEATURES.featured.find(x=>x.aid===aid);
 let catalog;for(const v of Object.values(CATALOG)){catalog=v.items.find(x=>x.aid===aid);if(catalog)break;}
 const sourceAid=MAIN_QC.items[aid]?aid:known?QC_AID_BY_ID[known.id]:aid;
 const saved=MAIN_QC.items[sourceAid];
 let p={...(catalog||{}),...(known||{}),aid,sourceQc:saved?.qc||[],qcStatus:saved?.status==='error'?'unavailable':saved?.status||'unavailable'};
 if(saved?.id)p.id=saved.id;
 if(sourceAid){
  try{
   const s=await remote('https://kakobuymake.com/?m=home&c=View&a=index&aid='+sourceAid),clean=s.replace(/<!--[\s\S]*?-->/g,'');
   const current=fromMainListing(clean,saved?.id||known?.id);
   Object.assign(p,current);
   const title=strip((clean.match(/<h1[^>]*class="product-title"[^>]*>([\s\S]*?)<\/h1>/)||[])[1]);if(title)p.title=title;
   const price=clean.match(/class="current-price price"[^>]*>\$?([\d.]+)/);if(price)p.price=+price[1];
  }catch{if(!known&&!catalog&&!saved)return null;}
 }
 p.cat=p.cat||2;
 // Every listing uses the main-site QC gallery, including curated homepage products.
 // Keep seller carousel metadata separate; it never supplies warehouse references.
 if(p.id&&(!known||aid==='7896594713')){
  try{Object.assign(p,fromWeidian(await remote('https://weidian.com/item.html?itemID='+p.id,3600)));if(p.gallery.length)p.image=p.gallery[0];}catch{p.gallery=[];p.sourceAvailable=false;}
 }
 return p;
}
function makeContext(req){const u=new URL(req.url),lang=I18N[u.searchParams.get('lang')]?u.searchParams.get('lang'):'en',t={...I18N.en,...I18N[lang]};const curr=(u.searchParams.get('currency')||'USD').toUpperCase();return{u,lang,t,curr:/^[A-Z]{3}$/.test(curr)?curr:'USD',link:(path,extras={})=>{const url=new URL(path,u.origin);if(lang!=='en')url.searchParams.set('lang',lang);if(curr!=='USD')url.searchParams.set('currency',curr);for(const [k,v]of Object.entries(extras))if(v!=null&&v!=='')url.searchParams.set(k,v);return url.pathname+url.search+url.hash;}};}
function headingName(p,t){if(t.native==='English'&&p.nameEn)return p.nameEn;if(t.native==='简体中文')return p.title||t.productTypes[p.cat-2];let model=(p.title||'').match(/\b(?:NB\s*\d+|SHOX|J4\s*RETRO|XT-?\d+|Kayano\s*\d+|[0-9]{2}[A-Z][0-9][-a-z0-9]*)\b/i)?.[0]||'';return t.productTypes[Math.max(0,p.cat-2)] +(model?' · '+model:'')+' / '+(p.id||p.aid);}
function price(p,t){return `<span class="price" data-usd="${p.price??''}" data-cny="${p.cny??''}">${p.price!=null?'$'+p.price.toFixed(2):'¥'+(p.cny||0).toFixed(2)}</span>`;}
function card(p,c,i){const{t,link}=c;return `<article class="product"><a class="product-image" href="${link('/product/'+p.aid)}"><img src="${esc(imageURL(p.image))}" alt="${esc(headingName(p,t))}" loading="${i<4?'eager':'lazy'}" width="600" height="600"><span class="open-arrow" aria-hidden="true"><span class="arrow ne" aria-hidden="true"></span></span></a><div class="product-meta"><span>${esc(t.shortCategories[p.cat-2])}</span><span>${String(i+1).padStart(2,'0')}</span></div><a class="product-title" href="${link('/product/'+p.aid)}">${esc(headingName(p,t))}</a><div class="product-bottom">${price(p,t)}<a href="${link('/product/'+p.aid)}">${esc(t.details)} <span aria-hidden="true"><span class="arrow ne" aria-hidden="true"></span></span></a></div></article>`;}
function shell(c,body,title,description,extra=''){const{t,lang,curr,u,link}=c;const canonical=new URL(u.pathname,SITE_ORIGIN),analytics=(u.hostname==='ootdbuysheetdesk.com'||u.hostname==='www.ootdbuysheetdesk.com')?`<script async src="https://www.googletagmanager.com/gtag/js?id=G-SN1WS560YB"></script><script>window.dataLayer=window.dataLayer||[];function gtag(){dataLayer.push(arguments)}gtag('js',new Date());gtag('config','G-SN1WS560YB');</script>`:'';if(lang!=='en')canonical.searchParams.set('lang',lang);if((u.pathname==='/finds'||u.pathname.startsWith('/category/'))&&+u.searchParams.get('page')>1)canonical.searchParams.set('page',u.searchParams.get('page'));return `<!doctype html><html lang="${lang}" dir="${lang==='ar'?'rtl':'ltr'}"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>${esc(title)} | OOTDBuy Sheetdesk</title><meta name="description" content="${esc(description)}"><meta name="theme-color" content="#fffaf5"><link rel="icon" href="/favicon.ico"><link rel="canonical" href="${canonical.href}">${Object.keys(I18N).map(l=>`<link rel="alternate" hreflang="${l}" href="${SITE_ORIGIN+u.pathname+(l==='en'?'':'?lang='+l)}">`).join('')}<link rel="alternate" hreflang="x-default" href="${SITE_ORIGIN+u.pathname}"><meta property="og:title" content="${esc(title)}"><meta property="og:description" content="${esc(description)}"><meta property="og:type" content="website"><meta property="og:url" content="${canonical.href}"><style>${CSS}</style>${extra}${analytics}</head><body><header class="header"><div class="header-inner"><a class="brand" href="${link('/')}" aria-label="OOTDBuy Sheetdesk home"><img src="/favicon.ico" alt="OOTDBuy" width="32" height="32"><span>ootdbuy</span></a><nav class="desktop-nav" aria-label="Main"><a href="${link('/')}" ${u.pathname==='/'?'aria-current="page"':''}>Home</a><a href="${link('/finds')}">${esc(t.spreadsheet)} <span class="arrow ne" aria-hidden="true"></span></a><a href="${link('/categories')}" ${u.pathname==='/categories'?'aria-current="page"':''}>${esc(t.categoriesNav)}</a><a href="${link('/image-search')}" ${u.pathname==='/image-search'?'aria-current="page"':''}>${esc(t.imageSearch.nav)}</a></nav><div class="tools"><div class="popover-wrap"><button class="tool" data-pop="languages" aria-expanded="false" aria-label="${esc(t.language)}"><span class="globe">◎</span> ${lang==='zh-CN'?'中文':lang.toUpperCase()} <span class="chev">⌄</span></button><div class="popover languages" id="languages" hidden><p>${esc(t.language)}</p><div class="language-grid">${Object.entries(I18N).map(([l,v])=>`<a href="${link(u.pathname,{...Object.fromEntries(u.searchParams),lang:l,currency:curr})}" lang="${l}" ${l===lang?'aria-current="true"':''}>${esc(v.native)}${l===lang?' ✓':''}</a>`).join('')}</div></div></div><div class="popover-wrap"><button class="tool" data-pop="currencies" aria-expanded="false" aria-label="${esc(t.currency)}">${curr} <span class="chev">⌄</span></button><div class="popover currencies" id="currencies" hidden><p>${esc(t.currency)}</p><div class="currency-grid">${['USD','EUR','GBP','CAD','AUD','CNY','CHF','SEK','NOK','DKK','PLN','CZK','HUF','RON','BGN','TRY','JPY','KRW','AED','SAR','NZD','SGD','HKD','TWD','THB','MYR','IDR','INR','PHP','VND','BRL','MXN','ZAR','ILS','ISK','UAH'].map(v=>`<button data-currency="${v}" ${v===curr?'aria-current="true"':''}>${v}${v===curr?' ✓':''}</button>`).join('')}</div></div></div><a class="register" href="${SIGNUP}" target="_blank" rel="sponsored noopener">Join OOTDBuy <span><span class="arrow ne" aria-hidden="true"></span></span></a><button class="menu-button tool" data-pop="mobile-menu" aria-label="${esc(t.more)}" aria-expanded="false"><span class="burger" aria-hidden="true"></span></button></div></div><nav id="mobile-menu" class="mobile-menu" hidden><a href="${link('/')}" ${u.pathname==='/'?'aria-current="page"':''}>Home</a><a href="${link('/finds')}">${esc(t.spreadsheet)} <span class="arrow ne" aria-hidden="true"></span></a><a href="${link('/categories')}" ${u.pathname==='/categories'?'aria-current="page"':''}>${esc(t.categoriesNav)}</a><a href="${link('/image-search')}" ${u.pathname==='/image-search'?'aria-current="page"':''}>${esc(t.imageSearch.nav)}</a></nav></header>${body}<footer><div class="footer-top"><a class="footer-logo" href="${link('/')}">ootdbuy</a><p>${esc(t.footer)}</p><a href="#top" aria-label="Back to top"><span class="arrow n" aria-hidden="true"></span></a></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} OOTDBuy Sheetdesk</span><p>${esc(t.affiliate)}</p></div></footer><script>window.DESK=${JSON.stringify({lang,curr,copied:t.copied})};${CLIENT}</script></body></html>`;}
function categories(c,compact=false){const{t,link,u}=c;const ix=SLUGS.indexOf(u.pathname.split('/')[2]),description=ix>=0?t.categoryDescriptions[ix]:t.selectedDesc;return `${compact?`<p class="category-page-description">${esc(description)}</p>`:''}<div class="category-index ${compact?'compact':''}">${SLUGS.map((s,i)=>`<a href="${link('/category/'+s)}" ${u.pathname==='/category/'+s?'aria-current="page"':''}><span class="category-n">${String(i+1).padStart(2,'0')}</span><span>${esc(t.shortCategories[i])}</span><span class="category-count">${CATALOG[i+2].total}</span><span class="category-arrow"><span class="arrow ne" aria-hidden="true"></span></span></a>`).join('')}</div>`;}
function categoriesOverview(c){const{t,link}=c;const cards=SLUGS.map((slug,i)=>'<a class="category-guide-card" href="'+link('/category/'+slug)+'"><div class="category-guide-top"><span class="category-guide-number">'+String(i+1).padStart(2,'0')+'</span><h2>'+esc(t.shortCategories[i])+'</h2></div><p>'+esc(t.categoryDescriptions[i])+'</p></a>').join('');return shell(c,'<main id="top" class="categories-page wrap"><header class="categories-page-heading"><div><span class="eyebrow">OOTDBUY CATEGORY GUIDE</span><h1>'+esc(t.categoriesTitle)+'<span class="red-dot">.</span></h1></div><p>'+esc(t.categoriesIntro)+'</p></header><div class="category-guide-grid">'+cards+'</div></main>',t.categoriesTitle,t.categoriesIntro);}
function homeCategories(c){const{t,link}=c;const total=Object.values(CATALOG).reduce((n,v)=>n+v.items.length,0);return `<section class="home-category-section wrap" id="categories" aria-labelledby="home-category-title"><div class="home-category-heading"><div><span class="eyebrow">01 / OOTDBUY DIRECTORY</span><h2 id="home-category-title">${esc(t.index)}<span class="red-dot">.</span></h2></div><a href="${link('/categories')}">${total.toLocaleString('en-US')} ${esc(t.item)} <span class="arrow ne" aria-hidden="true"></span></a></div><nav class="home-category-grid" aria-label="${esc(t.index)}">${SLUGS.map((slug,i)=>`<a href="${link('/category/'+slug)}"><span class="home-category-number">${String(i+1).padStart(2,'0')}</span><strong>${esc(t.shortCategories[i])}</strong><span class="home-category-total">${CATALOG[i+2].total.toLocaleString('en-US')} ${esc(t.item)}</span><span class="home-category-arrow"><span class="arrow ne" aria-hidden="true"></span></span></a>`).join('')}</nav></section>`;}
function homeSearch(c){const{t,lang,curr,link}=c,s=t.imageSearch;return `<div class="home-search-tools"><form class="home-search" id="search" action="/finds" method="get" role="search"><label for="home-search-input">${esc(t.browse)}</label><div><input id="home-search-input" name="q" type="search" placeholder="${esc(t.browse)}…" autocomplete="off">${lang!=='en'?`<input type="hidden" name="lang" value="${esc(lang)}">`:''}${curr!=='USD'?`<input type="hidden" name="currency" value="${esc(curr)}">`:''}<button type="submit">${esc(t.browse)}<span class="arrow e" aria-hidden="true"></span></button></div></form><a class="image-search-trigger" href="${link('/image-search')}"><span class="camera-icon" aria-hidden="true"></span>${esc(s.open)}</a></div>`;}
function imageSearchPage(c){const s=c.t.imageSearch,items=Object.values(CATALOG).flatMap(v=>v.items).filter(p=>IMAGE_FEATURES[p.aid]?.length).map(p=>({aid:p.aid,title:headingName(p,c.t),category:c.t.shortCategories[p.cat-2],categoryKey:p.cat,image:imageURL(p.image),features:IMAGE_FEATURES[p.aid]}));const widget=`<div class="home-search-tools image-search-page-tools"><button type="button" id="image-search-trigger" aria-controls="image-search-panel" aria-expanded="true" hidden>${esc(s.open)}</button><section class="image-search-panel image-search-page-panel" id="image-search-panel" aria-labelledby="image-search-title" data-ready="${esc(s.ready)}" data-matching="${esc(s.matching)}" data-invalid="${esc(s.invalid)}" data-exact="${esc(s.exact||'Exact match')}"><div class="image-search-heading"><div><span class="eyebrow">VISUAL SEARCH</span><h2 id="image-search-title">${esc(s.title)}</h2></div><button type="button" id="image-search-close" aria-label="${esc(s.clear)}">×</button></div><div class="image-search-upload"><input id="image-search-input" type="file" accept="image/jpeg,image/png,image/webp" hidden><label for="image-search-input"><span class="camera-icon" aria-hidden="true"></span><strong>${esc(s.drop)}</strong><small>${esc(s.note)}</small></label><div class="image-search-preview" id="image-search-preview" hidden><img id="image-search-preview-image" alt=""><button type="button" id="image-search-clear">${esc(s.clear)}</button></div></div><div class="image-search-actions"><p id="image-search-status" role="status" aria-live="polite"></p></div><div class="image-search-results" id="image-search-results" hidden><h3>${esc(s.results)}</h3><div></div><nav class="image-search-pages" aria-label="${esc(s.results)}"><button type="button" data-image-page="0" aria-current="page">1</button><button type="button" data-image-page="1">2</button><button type="button" data-image-page="2">3</button></nav></div><script type="application/json" id="image-search-index">${JSON.stringify(items).replace(/</g,'\\u003c')}</script></section></div>`;return shell(c,'<main id="top" class="image-search-page wrap"><header class="image-search-page-heading"><span class="eyebrow">OOTDBUY VISUAL SEARCH</span><h1>'+esc(s.title)+'<span class="red-dot">.</span></h1><p>'+esc(s.note)+'</p></header>'+widget+'</main>',s.nav,s.note);}
function homeHow(c){const{t}=c;const steps=[t.steps[1],[t.photosTitle,t.photosText],t.steps[2]];return `<section class="home-how wrap" aria-labelledby="home-how-title"><div class="home-how-heading"><span class="eyebrow">03 / HOW IT WORKS</span><h2 id="home-how-title">${esc(t.guideTeaser)}</h2></div><div class="home-how-grid">${steps.map((step,i)=>`<article><span>${String(i+1).padStart(2,'0')}</span><h3>${esc(step[0])}</h3><p>${esc(step[1])}</p></article>`).join('')}</div></section>`;}
function spotlightCard(p,c){const{t,link}=c;return `<article class="spotlight-card"><a class="spotlight-image" href="${link('/product/'+p.aid)}"><img src="${esc(imageURL(p.image))}" alt="${esc(headingName(p,t))}" loading="lazy" width="420" height="320"><span><span class="arrow ne" aria-hidden="true"></span></span></a><div><h3><a href="${link('/product/'+p.aid)}">${esc(headingName(p,t))}</a></h3>${price(p,t)}</div></article>`;}
function homeSpotlights(c){const{t,link}=c;const groups=[2,5,8],cards=groups.map(cat=>'<section class="spotlight-group"><div class="spotlight-heading"><h2>'+esc(t.categories[cat-2])+'</h2><a href="'+link('/category/'+SLUGS[cat-2])+'">'+esc(t.viewAll)+' <span class="arrow ne" aria-hidden="true"></span></a></div><p class="spotlight-description">'+esc(t.spotlightDescriptions[SLUGS[cat-2]])+'</p></section>').join('');return '<section class="home-spotlights wrap" aria-label="'+esc(t.index)+'"><div class="spotlights-label"><span class="eyebrow">02 / CATEGORY SPOTLIGHTS</span></div><div class="spotlight-groups">'+cards+'</div></section>';}
function homeCategoryGuide(c){const{t,link}=c;const cards=SLUGS.map((slug,i)=>'<a class="category-guide-card" href="'+link('/category/'+slug)+'"><div class="category-guide-top"><span class="category-guide-number">'+String(i+1).padStart(2,'0')+'</span><h2>'+esc(t.shortCategories[i])+'</h2></div><p>'+esc(t.categoryDescriptions[i])+'</p></a>').join('');return '<section class="home-category-guide wrap" aria-labelledby="home-category-guide-title"><header class="home-category-guide-heading"><div><span class="eyebrow">02 / CATEGORY GUIDE</span><h2 id="home-category-guide-title">'+esc(t.categoriesTitle)+'<span class="red-dot">.</span></h2></div><p>'+esc(t.categoriesIntro)+'</p></header><div class="category-guide-grid">'+cards+'</div></section>';}
function faqs(c){const{t}=c;return `<section class="faq-section wrap" id="faq"><div class="section-header"><div><span class="eyebrow">04 / ${esc(t.faq)}</span><h2>${esc(t.faqTitle)}</h2></div></div><div class="faq-layout"><div class="faq-topics">${t.topics.map((v,i)=>`<a href="#faq-group-${i}"><span>0${i+1}</span>${esc(v)} <span><span class="arrow se" aria-hidden="true"></span></span></a>`).join('')}</div><div class="faq-groups">${t.topics.map((v,i)=>`<div class="faq-group" id="faq-group-${i}"><h3>${esc(v)}</h3>${t.questions.slice(i*4,i*4+4).map(([q,a])=>`<details open><summary>${esc(q)}<span>+</span></summary>${faqAnswer(a)}</details>`).join('')}</div>`).join('')}</div></div></section>`;}
function atlasEntry(p,c,i){const{t,link}=c;return `<article class="atlas-entry"><a class="atlas-photo" href="${link('/product/'+p.aid)}"><img src="${esc(imageURL(p.image))}" alt="${esc(headingName(p,t))}" loading="${i<6?'eager':'lazy'}" width="600" height="600"><span class="atlas-photo-arrow"><span class="arrow ne" aria-hidden="true"></span></span></a><div class="atlas-caption"><span class="atlas-entry-number">${String(i+1).padStart(2,'0')}</span><div class="atlas-entry-name"><span>${esc(t.shortCategories[p.cat-2])}</span><h3><a href="${link('/product/'+p.aid)}">${esc(headingName(p,t))}</a></h3></div><div class="atlas-entry-price">${price(p,t)}</div></div></article>`;}
function faqAnswer(a){return '<div class="faq-answer">'+String(a).split(/\n\n+/).filter(Boolean).map(p=>'<p>'+esc(p)+'</p>').join('')+'</div>';}
function atlasFaq(c){const{t}=c;return `<section class="atlas-faq wrap" id="faq"><div class="atlas-faq-heading"><span class="eyebrow">${esc(t.faq)}</span><h2>${esc(t.faqTitle)}</h2></div><div class="atlas-faq-body"><div class="atlas-faq-tabs" role="tablist" aria-label="${esc(t.faq)}">${t.topics.map((v,i)=>`<button id="faq-control-${i}" role="tab" data-faq-tab="${i}" aria-controls="faq-panel-${i}" aria-selected="${i===0}" tabindex="${i===0?'0':'-1'}"><span>0${i+1}</span>${esc(v)}</button>`).join('')}</div><div class="atlas-faq-panels">${t.topics.map((v,i)=>`<section role="tabpanel" id="faq-panel-${i}" aria-labelledby="faq-control-${i}" ${i===0?'':'hidden'}>${t.questions.slice(i*4,i*4+4).map(([q,a])=>`<details open><summary>${esc(q)}<span>+</span></summary>${faqAnswer(a)}</details>`).join('')}</section>`).join('')}</div></div></section>`;}
function home(c){const{t,link,u}=c;const chapter=SLUGS.indexOf(u.searchParams.get('chapter')),set=Math.max(0,parseInt(u.searchParams.get('set'))||0);let featured=chapter<0?FEATURES.featured:CATALOG[chapter+2].items.slice(0,12);if(set){const pool=chapter<0?Object.values(CATALOG).flatMap(v=>v.items):CATALOG[chapter+2].items;featured=Array.from({length:Math.min(12,pool.length)},(_,i)=>pool[(set*13+i*29)%pool.length]);}const total=featured.length,pageCount=Math.max(1,Math.ceil(total/6)),page=Math.min(pageCount,Math.max(1,parseInt(u.searchParams.get('sheet'))||1)),visible=featured.slice((page-1)*6,page*6),label=chapter<0?t.selected:t.categories[chapter],allPath=chapter<0?'/finds':'/category/'+SLUGS[chapter];const pageLink=n=>link('/',{...(chapter<0?{}:{chapter:SLUGS[chapter]}),...(set?{set}:{}),sheet:n})+'#atlas';return shell(c,`<main id="top" class="home-v4"><section class="atlas-cover wrap"><div class="atlas-cover-inner"><div class="atlas-spine"><span>${esc(t.spreadsheet)}</span></div><div class="atlas-cover-title"><span class="eyebrow">OOTDBUY SHEETDESK</span><h1>${t.hero}</h1></div><div class="atlas-cover-note"><p>${esc(t.intro)}</p>${homeSearch(c)}<a href="#categories">${esc(t.explore)}<span class="arrow se" aria-hidden="true"></span></a></div><span class="atlas-cover-mark" aria-hidden="true">O.</span></div></section>${homeCategories(c)}<section class="atlas-section wrap" id="atlas"><div class="atlas-book"><div class="atlas-book-top"><details class="atlas-chapter"><summary><span class="atlas-chapter-label">${esc(t.index)}</span><strong>${esc(chapter<0?t.all:t.shortCategories[chapter])}</strong><span class="chev">⌄</span></summary><nav aria-label="${esc(t.index)}"><a href="${link('/')}#atlas" ${chapter<0?'aria-current="true"':''}>${esc(t.all)}<span>${Object.values(CATALOG).reduce((n,v)=>n+v.items.length,0).toLocaleString('en-US')}</span></a>${SLUGS.map((slug,i)=>`<a href="${link('/',{chapter:slug})}#atlas" ${chapter===i?'aria-current="true"':''}>${esc(t.shortCategories[i])}<span>${CATALOG[i+2].total}</span></a>`).join('')}</nav></details><div class="atlas-page-nav" aria-label="${esc(t.previous)} / ${esc(t.next)}">${page>1?`<a href="${pageLink(page-1)}" aria-label="${esc(t.previous)}"><span class="arrow w" aria-hidden="true"></span></a>`:`<span class="atlas-nav-disabled"><span class="arrow w" aria-hidden="true"></span></span>`}<span><strong>${String(page).padStart(2,'0')}</strong><i>/</i>${String(pageCount).padStart(2,'0')}</span>${page<pageCount?`<a href="${pageLink(page+1)}" aria-label="${esc(t.next)}"><span class="arrow e" aria-hidden="true"></span></a>`:`<span class="atlas-nav-disabled"><span class="arrow e" aria-hidden="true"></span></span>`}</div><a class="atlas-shuffle" href="${link('/',{...(chapter<0?{}:{chapter:SLUGS[chapter]}),set:set+1})}#atlas"><span class="refresh-icon" aria-hidden="true"></span><span>${esc(t.refresh)}</span></a></div><div class="atlas-spread-heading"><div><span class="atlas-chapter-number">${chapter<0?'00':String(chapter+1).padStart(2,'0')}</span><h2>${esc(label)}</h2></div><p>${esc(t.selectedDesc)}</p></div><div class="atlas-spread">${visible.map((p,i)=>atlasEntry(p,c,(page-1)*6+i)).join('')}</div><div class="atlas-book-bottom"><span>${String((page-1)*6+1).padStart(2,'0')}—${String(Math.min(page*6,total)).padStart(2,'0')} / ${total}</span><a href="${link(allPath)}">${esc(t.viewAll)}<span class="arrow ne" aria-hidden="true"></span></a></div></div></section>${homeHow(c)}${homeCategoryGuide(c)}${atlasFaq(c)}</main>`,'OOTDBuy Spreadsheet — Product Finds & QC Photos',t.intro,`<script type="application/ld+json">${JSON.stringify({'@context':'https://schema.org','@type':'FAQPage',mainEntity:t.questions.map(([q,a])=>({'@type':'Question',name:q,acceptedAnswer:{'@type':'Answer',text:a}}))}).replace(/</g,'\\u003c')}</script>`);}

async function collection(c,cat){const{t,u,link}=c;const page=Math.max(1,parseInt(u.searchParams.get('page'))||1),sort=u.searchParams.get('sort')||'newest',query=(u.searchParams.get('q')||'').trim();let all=cat?[...CATALOG[cat].items]:Object.values(CATALOG).flatMap(v=>v.items);if(query){const needle=query.toLocaleLowerCase();all=all.filter(p=>[p.title,p.nameEn,t.shortCategories[p.cat-2],t.categories[p.cat-2],p.id,p.aid].some(v=>String(v||'').toLocaleLowerCase().includes(needle)));}if(sort==='low')all.sort((a,b)=>(a.price||0)-(b.price||0));else if(sort==='high')all.sort((a,b)=>(b.price||0)-(a.price||0));else all.sort((a,b)=>+b.aid-+a.aid);const data={items:all.slice((page-1)*48,page*48),pages:Math.max(1,Math.ceil(all.length/48)),total:all.length};const items=data.items;const title=cat?t.categories[cat-2]:t.all;return shell(c,`<main id="top" class="collection wrap"><div class="breadcrumb"><a href="${link('/')}">OOTDBuy Sheetdesk</a><span>/</span>${esc(title)}</div><div class="collection-title"><div><span class="eyebrow">OOTDBUY SPREADSHEET / ${esc(t.index)}</span><h1>${esc(title)}<span class="red-dot">.</span></h1></div><p>${data.total.toLocaleString('en-US')} ${esc(t.item)}</p></div>${categories(c,true)}<div class="collection-controls"><span>${esc(t.browse)} <span class="subtle">/ ${page} · ${data.pages}</span></span><div><label>${esc(t.sort)} <select id="sort"><option value="newest" ${sort==='newest'?'selected':''}>${esc(t.newest)}</option><option value="low" ${sort==='low'?'selected':''}>${esc(t.low)}</option><option value="high" ${sort==='high'?'selected':''}>${esc(t.high)}</option></select></label><div class="column-controls" aria-label="${esc(t.columns)}"><button data-cols="3" aria-label="3 ${esc(t.columns)}">▥</button><button data-cols="4" class="active" aria-label="4 ${esc(t.columns)}">▦</button></div></div></div>${data.error?`<p class="notice">${esc(t.unavailable)}</p>`:''}<div class="product-grid">${items.map((p,i)=>card(p,c,i)).join('')}</div>${!items.length?`<p class="empty">${esc(t.empty)}</p>`:''}<div class="pagination">${page>1?`<a href="${link(u.pathname,{page:page-1,sort,...(query?{q:query}:{})})}"><span class="arrow w" aria-hidden="true"></span> ${esc(t.previous)}</a>`:'<span></span>'}<span>${page} / ${data.pages}</span>${page<data.pages?`<a href="${link(u.pathname,{page:page+1,sort,...(query?{q:query}:{})})}">${esc(t.next)} <span class="arrow e" aria-hidden="true"></span></a>`:'<span></span>'}</div></main>`,title+' — OOTDBuy Spreadsheet',t.selectedDesc);}
async function detail(c,aid){const{t,link}=c,p=await product(aid);if(!p)return new Response(shell(c,`<main class="wrap empty"><h1>${esc(t.notFound)}</h1><a href="${link('/finds')}">${esc(t.back)}</a></main>`,t.notFound,t.notFound),{status:404,headers:{'content-type':'text/html;charset=utf-8'}});const title=headingName(p,t),gallery=p.gallery||[],buy='https://ootdbuy.com/goods/details?id='+encodeURIComponent(p.id)+'&channel=weidian&inviteCode=endoren';const qc=p.sourceQc||[];return shell(c,`<main class="detail-page wrap" id="top"><div class="breadcrumb"><a href="${link('/finds')}">${esc(t.back)}</a><span>/</span>${esc(t.shortCategories[p.cat-2])}<span>/</span>${p.id||p.aid}</div><div class="detail-layout"><div class="seller-gallery"><div class="gallery-top"><span>${esc(t.seller)}</span><span id="gallery-count">1 / ${gallery.length||1}</span></div>${gallery.length?`<div class="gallery-main"><img id="main-image" src="${esc(imageURL(gallery[0]))}" alt="${esc(title)}"><button id="gallery-prev" aria-label="${esc(t.previous)}"><span class="arrow w" aria-hidden="true"></span></button><button id="gallery-next" aria-label="${esc(t.next)}"><span class="arrow e" aria-hidden="true"></span></button></div><div class="thumbnails">${gallery.map((im,i)=>`<button data-gallery="${i}" class="${i===0?'active':''}" aria-label="${esc(t.seller)} ${i+1}"><img src="${esc(imageURL(im))}" alt="${esc(title)} ${i+1}" loading="lazy"></button>`).join('')}</div><script type="application/json" id="gallery-data">${JSON.stringify(gallery.map(imageURL)).replace(/</g,'\\u003c')}</script>`:`<p class="notice">${esc(t.unavailable)}</p>`}</div><div class="detail-info"><span class="eyebrow">${esc(t.shortCategories[p.cat-2])}${p.id?' / WEIDIAN':''}</span><h1>${esc(title)}</h1><div class="detail-price">${price(p,t)}</div><p class="price-note">${esc(t.priceNote)}</p><p class="rates-note">${esc(t.ratesNote)}</p>${p.id?`<a class="button primary purchase" href="${buy}" target="_blank" rel="sponsored noopener">${esc(t.buy)} <span><span class="arrow ne" aria-hidden="true"></span></span></a><a class="source-link" href="https://weidian.com/item.html?itemID=${p.id}" target="_blank" rel="noopener">${esc(t.source)} <span class="arrow ne" aria-hidden="true"></span></a><div class="detail-reference"><span>WEIDIAN ID</span><strong>${p.id}</strong><button id="copy-link" data-copy="https://weidian.com/item.html?itemID=${p.id}">${esc(t.copy)} <span class="arrow ne" aria-hidden="true"></span></button></div><details class="original-title"><summary>${esc(t.original)}</summary><p>${esc(p.sourceName||p.title)}</p></details>`:`<p class="notice">${esc(t.unavailable)}</p>`}</div></div><section class="qc-section"><div class="section-header"><div><span class="eyebrow">QC / WAREHOUSE</span><h2>${esc(t.qc)}</h2><p>${esc(t.qcNote)}</p></div></div>${qc.length?`<div class="qc-grid">${qc.map(im=>`<a href="${esc(imageURL(im))}" target="_blank" rel="noopener"><img src="${esc(imageURL(im))}" alt="${esc(t.qc)} ${p.id||p.aid}" loading="lazy"></a>`).join('')}</div>`:`<p class="notice">${esc(p.qcStatus==='unavailable'?t.unavailable:t.noQc)}</p>`}</section></main>`,title+' — Product Details & QC',t.priceNote);}
function imageFromBase64(base64,mime){return new Response(Uint8Array.from(atob(base64),c=>c.charCodeAt(0)),{headers:{'content-type':mime,'cache-control':'public,max-age=86400'}});}
export default {async fetch(request,env,ctx){const c=makeContext(request),{u}=c;try{if(u.pathname.startsWith('/asset/')){const data=ASSET_KEYS[u.pathname.split('/').pop()];return data?imageFromBase64(data,'image/webp'):new Response('Not found',{status:404});}if(u.pathname==='/image'){const src=u.searchParams.get('url');let target;try{target=new URL(src);}catch{return new Response('Bad URL',{status:400});}if(target.protocol!=='https:'||!['si.geilicdn.com','kakobuymake.com'].includes(target.hostname)||target.username||target.password)return new Response('Blocked source',{status:403});try{const im=await fetch(target.href,{headers:{'User-Agent':'Mozilla/5.0'},signal:AbortSignal.timeout(20000),cf:{cacheTtl:86400,cacheEverything:true}});if(!im.ok)return new Response('Unavailable',{status:502});return new Response(im.body,{headers:{'content-type':im.headers.get('content-type')||'image/jpeg','cache-control':'public,max-age=86400'}});}catch{return new Response('Unavailable',{status:502});}}if(u.pathname==='/favicon.ico')return imageFromBase64(ICON,'image/x-icon');if(u.pathname.startsWith('/guide-image/')){const data=GUIDE_IMAGES[+u.pathname.split('/').pop()];return data?imageFromBase64(data,'image/webp'):new Response('Not found',{status:404});}if(u.pathname==='/api/rates'){try{const d=JSON.parse(await remote('https://open.er-api.com/v6/latest/USD',21600));if(!d.rates)throw Error();return Response.json({rates:d.rates,updated:d.time_last_update_utc},{headers:{'cache-control':'public,max-age=21600'}});}catch{return Response.json({rates:{USD:1},unavailable:true});}}
if(u.pathname==='/robots.txt')return new Response('User-agent: *\nAllow: /\nSitemap: '+SITE_ORIGIN+'/sitemap.xml',{headers:{'content-type':'text/plain'}});if(u.pathname==='/sitemap.xml'){const paths=['/','/categories','/image-search','/finds',...SLUGS.map(s=>'/category/'+s),...Object.values(CATALOG).flatMap(v=>v.items).map(p=>'/product/'+p.aid),'/product/7896594713'];return new Response('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+paths.map(p=>`<url><loc>${SITE_ORIGIN+p}</loc></url>`).join('')+'</urlset>',{headers:{'content-type':'application/xml'}});}let html;if(u.pathname==='/')html=home(c);else if(u.pathname==='/categories')html=categoriesOverview(c);else if(u.pathname==='/image-search')html=imageSearchPage(c);else if(u.pathname==='/finds')html=await collection(c,null);else if(u.pathname.startsWith('/category/')){const ix=SLUGS.indexOf(u.pathname.split('/')[2]);if(ix<0)return new Response('Not found',{status:404});html=await collection(c,ix+2);}else if(/^\/product\/\d+$/.test(u.pathname))html=await detail(c,u.pathname.split('/')[2]);else return new Response('Not found',{status:404});if(html instanceof Response)return html;return new Response(html,{headers:{'content-type':'text/html;charset=utf-8','cache-control':'no-store','x-content-type-options':'nosniff','referrer-policy':'strict-origin-when-cross-origin'}});}catch(e){return new Response(shell(c,`<main class="wrap empty"><h1>${esc(c.t.unavailable)}</h1><a href="${c.link('/finds')}">${esc(c.t.back)}</a></main>`,c.t.unavailable,c.t.unavailable),{status:503,headers:{'content-type':'text/html;charset=utf-8'}});}}};
